-- EduSasa canonical 009: payment providers, receipts and notifications.
CREATE TABLE IF NOT EXISTS payment_provider_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, channel_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NULL, provider VARCHAR(60) NOT NULL, provider_reference VARCHAR(160) NULL, merchant_request_id VARCHAR(120) NULL, checkout_request_id VARCHAR(120) NULL, phone VARCHAR(30) NOT NULL, amount DECIMAL(14,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'KES', account_reference VARCHAR(120) NULL, status ENUM('initiated','pending','paid','failed','cancelled','expired') NOT NULL DEFAULT 'initiated', result_code VARCHAR(40) NULL, result_description VARCHAR(255) NULL, callback_token_hash CHAR(64) NOT NULL, request_payload JSON NULL, response_payload JSON NULL, callback_payload JSON NULL, paid_at DATETIME NULL, created_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_provider_tx_callback_token(callback_token_hash), UNIQUE KEY uq_provider_checkout_request(provider,checkout_request_id), KEY idx_provider_tx_school_status(school_id,status), KEY idx_provider_tx_student(school_id,student_id), KEY idx_provider_tx_invoice(school_id,invoice_id), KEY idx_provider_tx_provider_reference(provider,provider_reference)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_provider_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transaction_id BIGINT UNSIGNED NULL, provider VARCHAR(60) NOT NULL, event_key VARCHAR(180) NOT NULL, payload JSON NOT NULL, received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, processed_at DATETIME NULL, status ENUM('received','processed','failed') NOT NULL DEFAULT 'received', error_message VARCHAR(255) NULL, UNIQUE KEY uq_provider_event(provider,event_key), KEY idx_provider_event_transaction(transaction_id), KEY idx_provider_event_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fee_receipts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, payment_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, receipt_no VARCHAR(100) NOT NULL, issued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'KES', method VARCHAR(80) NOT NULL, reference VARCHAR(190) NULL, payer_name VARCHAR(190) NULL, snapshot_json JSON NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_fee_receipts_payment(payment_id), UNIQUE KEY uq_fee_receipts_number(school_id,receipt_no), KEY idx_fee_receipts_student_date(school_id,student_id,issued_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_notification_deliveries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, payment_id BIGINT UNSIGNED NOT NULL, receipt_id BIGINT UNSIGNED NULL, channel VARCHAR(30) NOT NULL, recipient VARCHAR(190) NOT NULL, template VARCHAR(100) NOT NULL, status ENUM('queued','sent','failed','skipped') NOT NULL DEFAULT 'queued', provider_reference VARCHAR(190) NULL, error_message VARCHAR(500) NULL, payload_json JSON NULL, sent_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_payment_notifications_payment(payment_id,created_at), KEY idx_payment_notifications_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
